"""Three pilot learning cycles. References and drills are shown only after submission."""
PILOT={
'sube-lokasyonu':dict(
 task='Yönetim kurulu karar dosyası: mevcut durum değerlendirmeniz, önerdiğiniz hedef durum ve başarı göstergeleri, kararınız ve gerekçesi.',
 transfer='buyume-formati',
 sections=[
 ('Mevcut durum ve hedef','D01, D05, D06, D09','Şirketin tek mağazası ve çevrim içi kanalı var. Mevcut mağaza cirosu Mayıs–Ekim arasında 2,12 milyondan 2,48 milyon TL’ye çıkmış; bu tek başına yeni şube talebini kanıtlamaz. Hedef ikinci şubenin açılması kadar şirketin sürdürülebilir ek katkısıdır. Yönetimin açık sınırı yatırım sonrası 2 milyon TL rezervdir. Adayın katkı, açılış tarihi veya hizmet için önerdiği ek hedefler şirketçe onaylanmış veri değil, gerekçelendirilmesi gereken öneridir.'),
 ('Finansal karşılaştırma','D03, D04, D05, D12','A/B/C aylık satış tahmini 1.536.000 / 1.620.000 / 1.428.000 TL; yeni şube faaliyet sonucu 137.600 / 285.600 / 271.200 TL’dir. Eski mağazanın sabit gideri değişmediği için taşınan satışın katkısı düşülür. Şirkete ek sonuç A 137.600, B 162.480, C 242.640 TL/ay olur. Vergi, finansman ve amortisman dahil değildir. D12 yatırımların alt kırılımıdır; D03 üzerine tekrar eklenmez. Yatırım sonrası proje nakdi A 3,2, B 4,8, C 5,4 milyon TL; D12 depozito/giriş içerir, ilk stok ve diğer işletme sermayesi ise henüz tamamlanmamıştır. Bu yüzden yalnız rezerv hesabıyla nihai imza önerilemez.'),
 ('Verinin sınırı','D07, D09, D10','120 yanıt gönüllü mevcut müşteri listesinden gelir; yeni bölge nüfusunu temsil ettiği söylenemez. Mevcut müşterinin gelirim demesi ek satış ile aktarımı ayırmaz. D10 kısa saha gözlemleri, D03 aylık tahminlerine eklenecek ziyaretçi değildir. Gün, saat ve sayım kapsamı standartlaştırılarak dönüşüm tahminleri sınanabilir. Mevcut mağaza altı aylık geçmişi yeni bölge için doğrudan tahmin modeli değildir.'),
 ('Birden fazla savunulabilir karar','D03, D08, D11','C ilk tahminle finansal açıdan güçlüdür; resmi erişim yazısı, dönüşüm ve açılış takvimi teyidine bağlı koşullu tercih savunulabilir. B daha düşük ek katkıya rağmen doğrulanmış erişim veya stratejik kapsama gerekçesiyle seçilebilir; satış aktarımı ve yükleme saati ele alınmalıdır. A’nın daha uzun kira ve yüksek yatırımını haklı çıkaracak ek kanıt gerekir. Eksik nakit ve izin bilgileri kritikse imzayı ertelemek de geçerli olabilir; tarih, araştırma maliyeti ve teklif kaybı karşılığı açıklanmalıdır. Hiçbir seçenek yalnız adı nedeniyle doğru sayılmaz.'),
 ('Karar değişim eşiği ve uygulama','D02, D03, D04, D08, D11','Diğer tahminler sabitken C’nin ek katkısı 14.000 × dönüşüm × 850 × 0,40 × 0,95 − 300.000’dir. B’nin 162.480 TL katkısıyla eşik dönüşüm yaklaşık %10,23’tür; bu tek başına stratejik karar eşiği değildir. 90 günlük planda kira/erişim teyidi, nakit planı, sorumlu ataması, ekip ve eğitim, kontrollü açılış ve tahmin-gerçekleşen takibi yer alabilir. İş geliştirme yöneticisi imza yetkisini üstlenmez. Hedef tutmadığında yeniden inceleme tarihi ve karar sahibi belirtilir.')],
 drills=[('Şirket etkisini yeniden kur','Bir şubenin aylık satışı 1.000.000 TL, katkı oranı %40, sabit gideri 250.000 TL. Satışın %15’i mevcut şubeden aktarılıyor; eski katkı oranı %30. Şube sonucu ve şirkete ek katkıyı ayrı göster.','Şube sonucu 150.000 TL, eski katkı kaybı 45.000 TL, şirkete ek katkı 105.000 TL/ay. Aktarılan 150.000 TL cironun tamamı kâr kaybı değildir.'),('Karar koşulunu görünür kıl','İlk tercihinin geçerli kalması için gerekli iki teyidi ve her teyit gelmezse alacağın kararı yaz.','Genel “araştırılmalı” ifadesi yerine hangi bilgi, kimden, ne zamana kadar ve kararı nasıl değiştireceği açıklanmalı. Bu açık uçlu çalışma otomatik değerlendirilmez.')],
 practices=[0,1,1,1,1]),
'nakit-toparlanma':dict(
 task='İlk dört hafta için yönetim karar dosyası: mevcut durum, önerilen hedef durum ve başarı göstergeleri, karar ve gerekçesi.',
 transfer='doksan-gun-toparlanma',
 sections=[
 ('Durum ve hedefin ayrılması','D01, D03, D05, D09','300.000 TL başlangıç nakdi, dört haftada 1.400.000 TL tahsilat ve 1.750.000 TL ödeme vardır. Dönem sonu açık 50.000 TL iken ara dönem en düşük bakiye eksi 250.000 TL’dir. Yönetimin hedefi her hafta sonu 100.000 TL tampon; gün içi asgari bakiye dosyası eksiktir. Nakit sorunu kanıtlanmıştır, fakat dosyada gelir tablosu olmadığı için şirketin kesin zarar ettiği veya iflas ettiği sonucu çıkarılamaz. Kalıcı toparlanma için marj, vade ve faaliyet verisi ayrıca gerekir.'),
 ('Baz tablo ve kaynak ihtiyacı','D03, D05, D06, D07','Hafta sonu baz bakiyeler 50.000 / −250.000 / −150.000 / −50.000 TL’dir. Tamponu sağlayan başlangıç kaynağı 350.000 TL olur; görüşülen 200.000 TL tek başına yetmez. R1–R5 zaten haftalık tahsilat planındadır; tekrar eklenmez. R6’nın 600.000 TL’si beşinci hafta ve sonrasına aittir. Ödeme alt listesi 1.750.000 TL ana toplamı doğrular; ayrı ek ödeme değildir.'),
 ('Koşullu birleşik plan','D02, D04, D08','200.000 TL tahsilatı üçüncü haftadan ikinciye almak ve 300.000 TL ödemeyi ikinciden dördüncüye taşımak desteksiz 50.000 / 250.000 / 150.000 / −50.000 TL verir. 150.000 TL başlangıç kaynağıyla 200.000 / 400.000 / 300.000 / 100.000 TL elde edilir. Bu, iki yazılı teyit ve kaynak onayına bağlı uygulanabilir bir örnektir; finansman gideri dahil değildir. Daha farklı, tutarı ve zamanı doğrulanmış bir birleşim de kabul edilebilir. Ödeme erteleme maliyet tasarrufu, erken tahsilat yeni gelir değildir.'),
 ('Operasyon etkisi ve eksik teyit','D02, D06, D07, D08, D10','Tedarikçi X ertelemesi kritik parça sevkini etkileyebilir; satın alma yazılı koşulu, operasyon hizmet etkisini, finans nakdi doğrular. R4 kabul imzası bekler; teknik belgenin sahibi ve son tarihi belirlenmelidir. Stok defter değeri 3 milyon TL olsa da 900.000 TL tahsisli, 600.000 TL eski model ve 400.000 TL proje fazlasıdır. Teknik uygunluk, alıcı, fiyat ve tahsilat tarihi olmadan bunlar nakde eklenmez. Personel ve diğer taahhütlerin tek taraflı değiştiği varsayılmaz.'),
 ('Alternatif ve kalıcı program','D04, D05, D08, D09','Yalnız erken tahsilatla tampon ihtiyacı 250.000 TL, yalnız ertelemeyle 150.000 TL’dir; ikinci seçenek matematiksel olarak yeterli olabilir, ancak son bakiyeyi tam sınırda bırakır ve onay/operasyon riskini ortadan kaldırmaz. Her iki aksiyonla da son hafta tamponu tam sınırdadır. Başarısız teyitte alternatif kaynak, doğrulanmış ek tahsilat veya onaylı taahhüt değişikliği tutar ve tarihle gösterilmelidir. İlk 48 saatte sahip ve teyitler, sonraki 90 günde haftalık kayan nakit planı, vade/marj incelemesi ve 8. hafta finansman geri ödemesi ele alınır.')],
 drills=[('Zaman kaydırmayı çift taraflı işle','İkinci haftanın 100.000 TL tahsilatı birinci haftaya alınıyor. Toplam dört haftalık tahsilat ve hafta sonu bakiyelerine etkisini anlat.','Birinci haftaya +100.000, ikinci hafta tahsilatına −100.000 yazılır. Birinci hafta bakiyesi artar; ikinci hafta sonu ve sonrası baz plana döner. Dört haftalık toplam değişmez.'),('Teyit gelmezse planı yenile','İlk tercihindeki bir tahsilat veya ödeme teyidi gerçekleşmezse hangi tutarı, hangi tarihte ve hangi yetkili kararıyla karşılayacağını yaz.','Belirsiz satış veya stok değeri otomatik nakit kaynağı sayılamaz. Revize bakiyeler, karar tarihi ve kaynağın doğrulanma durumu görünür olmalıdır.')],
 practices=[0,0,1,1,1,1]),
'geri-bildirim':dict(
 task='15 dakikalık görüşme akışı: mevcut durum değerlendirmesi, görüşmede paylaşılacak beklenti ve görüşmenin amacı.',
 transfer='ekip-yuku',
 sections=[
 ('Mevcut durumun dengeli anlatımı','D01, D03, D06','Son hafta 120/100 dosyayla hacim hedefinin %120’si tamamlanmış, 10/120=%8,33 yeniden işlem kaydedilmiştir. Önceki hafta 5/100=%5’tir. Son hafta oranı önceki haftadan 3,33, onaylı %4 hedeften 4,33 yüzde puan yüksektir. Altı hafta toplamı 620 dosya ve 32 yeniden işlemdir; yaklaşık %5,16. Son haftadaki değişim incelenmelidir, fakat iş karması ve hata sınıflaması netleşmeden kişinin tutumu hakkında sonuç çıkarılmaz.'),
 ('Kayıt ile nedenin ayrılması','D04, D07, D08','On kaydın dördü iç kontrolden, altısı müşteri kaynaklıdır. Altı dosyada kapsam değişikliği açıklaması olması altısının da hatasız olduğunu kanıtlamaz. Kalite uzmanıyla aynı tanım üzerinden inceleme yapılır; bütün altı kayıt kapsam dışı kabul edilirse koşullu oran 4/120=%3,33 olur, bu teyit öncesi resmî sonuç değildir. Beş dosyalık ortak inceleme öğretici olabilir, fakat tüm on kaydın sınıflamasının yerine geçmez. Acil iş ve iki saat destek çalışanın açıklamasıdır; doğrulanır ve iş planına etkisi incelenir.'),
 ('Görüşme örneği ve dinleme','D03, D04, D05, D09','Örnek açılış: “Bu hafta 120 dosya tamamladın. Aynı kayıtta on dosyanın yeniden işlem gördüğü yazıyor. Hacmi, yeni alanın kullanımını ve kayıtların nedenlerini birlikte anlamak istiyorum. Senin açısından hafta nasıl geçti?” Ardından kesmeden dinlemek, somut örneği istemek ve anlaşılanı özetlemek uygundur. Bu örneği kelimesi kelimesine kullanmak ölçüt değildir. Mevcut dosya kişilik etiketi, disiplin kararı veya ücret kararı için dayanak sağlamaz.'),
 ('Beklenti ve destek mutabakatı','D02, D03, D05, D08','Onaylı yeniden işlem hedefi %4 olarak korunur. Bu, tek taraflı ve koşulsuz “haftaya sıfır hata” sözüne çevrilmez. Yeni alan için ortak dosya incelemesi, destek kanalı, acil iş ve mentorluk zamanının görünürlüğü, çalışanın kontrol adımı ve liderin iş dağılımı sorumluluğu yazılılaştırılır. Çalışan görüşe katılmıyorsa itirazı kayda geçer; mutabakat sağlanmış gibi gösterilmez. Kabul standardını değiştirmek bölüm yöneticisinin yetkisindedir.'),
 ('Takip ve alternatif yaklaşım','D05, D06, D09','İlk iki gün beş dosya birlikte incelenebilir; iki haftalık takipte hacim, iş karması ve aynı sınıflamayla yeniden işlem birlikte görülür. Örnek seçiminin nasıl yapıldığı belirtilir. Görüşme 15 dakikada tamamlanmıyorsa ertesi gün 20 dakikalık devam seçeneği vardır. Sınıflama teyidi öncesi destek planıyla ilerlemek veya görüşmede ön inceleme yapıp hedef takibini teyit sonrasına bırakmak savunulabilir; kararın sınırı ve yeniden görüşme tarihi açık olmalıdır. Tek düşük oran kalıcı gelişim kanıtı değildir.')],
 drills=[('Gözlem ile yorumu ayır','“Arda dikkatsiz, işi önemsemiyor” ifadesini dosyadaki doğrulanmış veriye ve açık bir araştırma sorusuna dönüştür.','Kişilik/niyet atfetmeden sayılan çıktı ve yeniden işlem kaydını söylemek; yeni alanın uygulanmasını ve örnek olayları sormak beklenir. Çalışanın açıklaması doğrulanmış neden değildir.'),('İki tarafın sorumluluğunu yaz','İki haftalık takip için çalışanın bir adımını, liderin sağlayacağı desteği, ölçülecek çıktıyı ve görüşme tarihini yaz.','Yalnız çalışana görev vermek veya yalnız destek sözü vermek eksik kalır. Ölçütün paydası/dönemi, destek sahibi ve takip tarihi açıklanmalıdır.')],
 practices=[0,0,1,1])}
for c in CASES:
 if c['id'] not in PILOT:continue
 p=PILOT[c['id']];c['version']='3.0.0';c['tasks'][0]=p['task']
 c['learning']={'transfer':p['transfer'],'sections':[dict(title=t,sources=s,text=x) for t,s,x in p['sections']], 'drills':[dict(title=t,prompt=q,reference=r) for t,q,r in p['drills']]}
 for i,r in enumerate(c['rubric']):
  r['anchors']=['İlgili dayanak veya beklenen çıktı henüz gösterilmemiş.', 'İlgili konuya değinilmiş; veri bağlantısı ya da gerekçe önemli ölçüde eksik.', 'Ölçüt, aday yanıtından gösterilen dayanakla karşılanıyor; sınır veya uygulamada açıklık var.', 'Ölçüt dayanaklı biçimde karşılanıyor; ilgili varsayım, sınır veya alternatif de açıklanmış.']
  r['practice']=p['practices'][i]
